#!/usr/bin/env python3
"""Apply text edits to a .docx as Word tracked changes. Standard library only.

Usage:
  python3 redline.py text  IN.docx                 # print the paragraphs, one per line, to see exact wording
  python3 redline.py apply IN.docx OUT.docx EDITS.json [--author NAME]

EDITS.json is a list of edits, applied in order:
  {"find": "exact text as it appears in one paragraph", "replace": "new text"}   # reword (replace "" to delete)
  {"find": "anchor text", "insert_after": "text to add after the anchor"}         # add without deleting

Rules the script enforces:
  - "find" must sit inside ONE paragraph and must match exactly once in the document, or the edit is
    refused and reported (nothing is guessed). Use "occurrence": N (1-based) when a phrase repeats.
  - Formatting of the first matched run is reused for inserted text.
  - Runs holding tabs, breaks, fields or images are never split; a match cannot cross them.
Exit code 1 if any edit was refused, so a caller notices.
"""
import json, re, sys, zipfile, datetime, html

W_P = re.compile(r'<w:p(?=[\s>])[^>]*>.*?</w:p>', re.S)
W_R = re.compile(r'<w:r(?=[\s>])[^>]*>.*?</w:r>', re.S)
RPR = re.compile(r'<w:rPr>.*?</w:rPr>', re.S)
T_ONLY = re.compile(r'^<w:r(?=[\s>])[^>]*>(?:<w:rPr>.*?</w:rPr>)?<w:t(?:\s[^>]*)?>(.*?)</w:t></w:r>$', re.S)
OPAQUE = '\x00'


def unesc(s): return html.unescape(s)
def esc(s): return s.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;')


def runs_of(p):
    """(start, end, xml, text, splittable) for each run in paragraph xml p."""
    out = []
    for m in W_R.finditer(p):
        x = m.group(0)
        # skip runs nested inside ins/del already present
        pre = p[:m.start()]
        if pre.count('<w:ins ') > pre.count('</w:ins>') or pre.count('<w:del ') > pre.count('</w:del>'):
            continue
        t = T_ONLY.match(x)
        if t:
            out.append((m.start(), m.end(), x, unesc(t.group(1)), True))
        else:
            txt = ''.join(unesc(a) for a in re.findall(r'<w:t(?:\s[^>]*)?>(.*?)</w:t>', x, re.S))
            out.append((m.start(), m.end(), x, OPAQUE + txt + OPAQUE, False))
    return out


def para_text(p):
    return ''.join(r[3] for r in runs_of(p))


def mkrun(rpr, text, deleted=False):
    tag = 'w:delText' if deleted else 'w:t'
    return '<w:r>%s<%s xml:space="preserve">%s</%s></w:r>' % (rpr, tag, esc(text), tag)


class Ids:
    def __init__(self, start=9001): self.n = start
    def next(self):
        self.n += 1
        return self.n


def apply_edit(doc, edit, author, date, ids):
    find = edit['find']
    new = edit.get('replace')
    add = edit.get('insert_after')
    want = int(edit.get('occurrence', 1))
    hits = []
    for pm in W_P.finditer(doc):
        p = pm.group(0)
        if '<w:p ' in p[4:] or '<w:p>' in p[4:]:
            continue  # nested paragraph (text box); skip rather than risk corrupting it
        txt = para_text(p)
        i = txt.find(find)
        while i != -1:
            hits.append((pm, i))
            i = txt.find(find, i + 1)
    if not hits:
        return doc, 'not found'
    if len(hits) > 1 and 'occurrence' not in edit:
        return doc, 'matches %d times - add "occurrence"' % len(hits)
    if want > len(hits):
        return doc, 'occurrence %d requested, only %d found' % (want, len(hits))
    pm, idx = hits[want - 1]
    p = pm.group(0)
    runs = runs_of(p)
    a, b = idx, idx + len(find)
    if add is not None:
        a = b  # pure insertion point
    pos = 0
    pieces = []  # (run_start, run_end, replacement_xml)
    first_rpr = None
    last_touched = None
    for (s, e, x, t, ok) in runs:
        r0, r1 = pos, pos + len(t)
        pos = r1
        touches = (r0 < b and r1 > a) if a != b else (r0 < a <= r1)
        if not touches:
            continue
        if not ok:
            return doc, 'match crosses a tab, break or field - pick a shorter "find"'
        rpr_m = RPR.search(x)
        rpr = rpr_m.group(0) if rpr_m else ''
        if first_rpr is None:
            first_rpr = rpr
        lo, hi = max(a, r0) - r0, min(b, r1) - r0
        before, mid, after = t[:lo], t[lo:hi], t[hi:]
        xml = ''
        if before:
            xml += mkrun(rpr, before)
        if mid:
            xml += '<w:del w:id="%d" w:author="%s" w:date="%s">%s</w:del>' % (
                ids.next(), esc(author), date, mkrun(rpr, mid, deleted=True))
        marker = '\x01INS\x01'
        xml += marker
        if after:
            xml += mkrun(rpr, after)
        pieces.append([s, e, xml])
        last_touched = len(pieces) - 1
    if not pieces:
        return doc, 'could not map match to runs'
    ins_text = add if add is not None else new
    for k, pc in enumerate(pieces):
        if k == last_touched and ins_text:
            pc[2] = pc[2].replace('\x01INS\x01', '<w:ins w:id="%d" w:author="%s" w:date="%s">%s</w:ins>' % (
                ids.next(), esc(author), date, mkrun(first_rpr or '', ins_text)))
        else:
            pc[2] = pc[2].replace('\x01INS\x01', '')
    newp = p
    for s, e, xml in sorted(pieces, key=lambda z: -z[0]):
        newp = newp[:s] + xml + newp[e:]
    return doc[:pm.start()] + newp + doc[pm.end():], None


def cmd_text(path):
    with zipfile.ZipFile(path) as z:
        doc = z.read('word/document.xml').decode('utf8')
    for i, pm in enumerate(W_P.finditer(doc)):
        t = para_text(pm.group(0)).replace(OPAQUE, '')
        if t.strip():
            print('%3d  %s' % (i, t))


def cmd_apply(src, dst, edits_path, author):
    edits = json.load(open(edits_path))
    date = datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ')
    with zipfile.ZipFile(src) as z:
        items = [(i, z.read(i.filename)) for i in z.infolist()]
    doc = dict((i.filename, d) for i, d in items)['word/document.xml'].decode('utf8')
    ids, failed = Ids(), 0
    for n, ed in enumerate(edits, 1):
        doc, err = apply_edit(doc, ed, author, date, ids)
        label = (ed.get('find') or '')[:60]
        if err:
            failed += 1
            print('REFUSED %d: %s  [%s]' % (n, err, label))
        else:
            print('ok      %d: %s' % (n, label))
    with zipfile.ZipFile(dst, 'w', zipfile.ZIP_DEFLATED) as z:
        for info, data in items:
            if info.filename == 'word/document.xml':
                data = doc.encode('utf8')
            z.writestr(info, data)
    print('%d applied, %d refused -> %s' % (len(edits) - failed, failed, dst))
    return 1 if failed else 0


if __name__ == '__main__':
    a = sys.argv[1:]
    if a[:1] == ['text'] and len(a) == 2:
        cmd_text(a[1])
    elif a[:1] == ['apply'] and len(a) >= 4:
        author = a[a.index('--author') + 1] if '--author' in a else 'Claude'
        sys.exit(cmd_apply(a[1], a[2], a[3], author))
    else:
        print(__doc__)
        sys.exit(2)
